	return nil
}

problems.solution:
package main

func sortedSquares(nums []int) []int {
	n := len(nums)
	out := make([]int, n)
	l, r := 0, n-1
	for w := n - 1; w >= 0; w-- {
		a, b := nums[l]*nums[l], nums[r]*nums[r]
		if a > b {
			out[w] = a
			l++
		} else {
			out[w] = b
			r--
		}
	}
	return out
}

