func intersect(nums1 []int, nums2 []int) []int {
	return nil
}

problems.solution:
package main

func intersect(nums1 []int, nums2 []int) []int {
	if len(nums1) > len(nums2) {
		nums1, nums2 = nums2, nums1 // 用较小的数组建表
	}
	count := make(map[int]int, len(nums1))
	for _, v := range nums1 {
		count[v]++
	}
	var out []int
	for _, v := range nums2 {
		if count[v] > 0 {
			out = append(out, v)
			count[v]--
		}
	}
	return out
}

