func isPalindrome(s string) bool {
	return false
}

problems.solution:
package main

import "unicode"

func isPalindrome(s string) bool {
	r := []rune(s)
	i, j := 0, len(r)-1
	for i < j {
		if !isAlnum(r[i]) {
			i++
			continue
		}
		if !isAlnum(r[j]) {
			j--
			continue
		}
		if unicode.ToLower(r[i]) != unicode.ToLower(r[j]) {
			return false
		}
		i++
		j--
	}
	return true
}

func isAlnum(c rune) bool { return unicode.IsLetter(c) || unicode.IsDigit(c) }

