		"0P":                             false,
		"ab_a":                           true,
		".,":                             true,
		"No 'x' in Nixon":                true,
	}
	for in, want := range cases {
		if got := isPalindrome(in); got != want {
			t.Errorf("isPalindrome(%q) = %v，期望 %v", in, got, want)
		}
