package main

const base = 769 // 质数作为桶的数量，让 key 分布更均匀

type MyHashSet struct {
	buckets [base][]int
}

func Constructor() MyHashSet {
	return MyHashSet{}
}

func (s *MyHashSet) Add(key int) {
	if !s.Contains(key) {
		b := &s.buckets[key%base]
		*b = append(*b, key)
	}
}

func (s *MyHashSet) Remove(key int) {
	b := &s.buckets[key%base]
	for i, v := range *b {
		if v == key {
			(*b)[i] = (*b)[len(*b)-1]
			*b = (*b)[:len(*b)-1]
			return
		}
	}
}

func (s *MyHashSet) Contains(key int) bool {
	for _, v := range s.buckets[key%base] {
		if v == key {
			return true
		}
	}
	return false
}

