	s.Add(2)
	if !s.Contains(2) {
		t.Fatal("重复 Add 后仍应包含")
	}
	s.Remove(2)
	if s.Contains(2) {
		t.Fatal("Remove 后不应包含")
	}
	s.Remove(12345)

	for k := 0; k <= 1000000; k += 769 { // 全部落在同一个桶
		s.Add(k)
	}
	for k := 0; k <= 1000000; k += 769 {
		if !s.Contains(k) {
			t.Fatalf("应包含 %d", k)
		}
	}
	s.Remove(769 * 10)
	if s.Contains(769*10) || !s.Contains(769*11) {
		t.Fatal("同一个桶里删除一个元素不应影响其他元素")
	}
}

