func TestPrintInOrder(t *testing.T) {
	orders := [][3]int{{0, 1, 2}, {0, 2, 1}, {1, 0, 2}, {1, 2, 0}, {2, 0, 1}, {2, 1, 0}}
	for _, order := range orders {
		f := NewFoo()
		var mu sync.Mutex
		var out []string
		p := func(s string) func() {
			return func() { mu.Lock(); out = append(out, s); mu.Unlock() }
		}
		calls := []func(){
			func() { f.First(p("first")) },
			func() { f.Second(p("second")) },
			func() { f.Third(p("third")) },
		}
		var wg sync.WaitGroup
		for _, i := range order {
			wg.Add(1)
			go func() { defer wg.Done(); calls[i]() }()
			time.Sleep(2 * time.Millisecond) // 让后启动的 goroutine 真的晚一点
		}
		done := make(chan struct{})
		go func() { wg.Wait(); close(done) }()
		select {
		case <-done:
		case <-time.After(2 * time.Second):
			t.Fatalf("启动顺序 %v：超时（死锁？）", order)
		}
		if got := strings.Join(out, ","); got != "first,second,third" {
			t.Fatalf("启动顺序 %v：输出 %s", order, got)
		}
	}
