problems.solution:
package main

import "slices"

func threeSum(nums []int) [][]int {
	slices.Sort(nums)
	var res [][]int
	n := len(nums)
	for i := 0; i < n-2; i++ {
		if nums[i] > 0 {
			break // 最小的数都大于 0，后面不可能凑出 0
		}
		if i > 0 && nums[i] == nums[i-1] {
			continue // 第一个数去重
		}
		l, r := i+1, n-1
		for l < r {
			switch sum := nums[i] + nums[l] + nums[r]; {
			case sum < 0:
				l++
			case sum > 0:
				r--
			default:
				res = append(res, []int{nums[i], nums[l], nums[r]})
				for l < r && nums[l] == nums[l+1] {
					l++ // 第二个数去重
				}
				for l < r && nums[r] == nums[r-1] {
					r-- // 第三个数去重
				}
				l++
				r--
			}
		}
	}
	return res
}

