package main

func twoSum(numbers []int, target int) []int {
	l, r := 0, len(numbers)-1
	for l < r {
		switch s := numbers[l] + numbers[r]; {
		case s == target:
			return []int{l + 1, r + 1}
		case s < target:
			l++ // 和太小，左边换一个更大的数
		default:
			r-- // 和太大，右边换一个更小的数
		}
	}
	return nil
}

