problems.solution:
package main

import "math"

func minSubArrayLen(target int, nums []int) int {
	best := math.MaxInt
	sum, left := 0, 0
	for right, v := range nums {
		sum += v
		for sum >= target { // 窗口满足条件：记录长度，然后尝试缩小
			best = min(best, right-left+1)
			sum -= nums[left]
			left++
		}
	}
	if best == math.MaxInt {
		return 0
	}
	return best
}

