problems.solution:
package main

func findAnagrams(s string, p string) []int {
	if len(p) > len(s) {
		return nil
	}
	var need, win [26]int
	for i := 0; i < len(p); i++ {
		need[p[i]-'a']++
	}
	var res []int
	for i := 0; i < len(s); i++ {
		win[s[i]-'a']++ // 右边进窗口
		if i >= len(p) {
			win[s[i-len(p)]-'a']-- // 左边出窗口，窗口长度保持 len(p)
		}
		if i >= len(p)-1 && win == need {
			res = append(res, i-len(p)+1)
		}
	}
	return res
}

