problems.solution:
package main

func productExceptSelf(nums []int) []int {
	n := len(nums)
	out := make([]int, n)
	out[0] = 1
	for i := 1; i < n; i++ {
		out[i] = out[i-1] * nums[i-1] // 此时 out[i] = 左边所有数的乘积
	}
	right := 1 // 右边所有数的乘积
	for i := n - 1; i >= 0; i-- {
		out[i] *= right
		right *= nums[i]
	}
	return out
}

