import "testing"

func board(rows ...string) [][]byte {
	b := make([][]byte, len(rows))
	for i, r := range rows {
		b[i] = []byte(r)
	}
	return b
}

var valid = []string{
	"53..7....",
	"6..195...",
	".98....6.",
	"8...6...3",
	"4..8.3..1",
	"7...2...6",
	".6....28.",
	"...419..5",
	"....8..79",
}

// with 返回把第 r 行第 c 列改成 v 之后的盘面
func with(r, c int, v byte) [][]byte {
	b := board(valid...)
	b[r][c] = v
	return b
}

func TestIsValidSudoku(t *testing.T) {
	cases := []struct {
		name string
		b    [][]byte
		want bool
	}{
		{"有效盘面", board(valid...), true},
		{"第一列重复 8", with(0, 0, '8'), false},
		{"行内重复 7", with(0, 8, '7'), false},
		{"列内重复 1", with(0, 8, '1'), false},
		{"宫内重复 9", with(0, 2, '9'), false},
		{"空盘面", board(".........", ".........", ".........", ".........", ".........", ".........", ".........", ".........", "........."), true},
	}
	for _, c := range cases {
		if got := isValidSudoku(c.b); got != c.want {
			t.Errorf("%s：isValidSudoku = %v，期望 %v", c.name, got, c.want)
		}
	}
}

