	return []int{-1, -1}
}

problems.solution:
package main

func searchRange(nums []int, target int) []int {
	// lower 返回第一个 >= x 的下标
	lower := func(x int) int {
		lo, hi := 0, len(nums)
		for lo < hi {
			mid := lo + (hi-lo)/2
			if nums[mid] < x {
				lo = mid + 1
			} else {
				hi = mid
			}
		}
		return lo
	}
	l := lower(target)
	if l == len(nums) || nums[l] != target {
		return []int{-1, -1}
	}
	return []int{l, lower(target+1) - 1} // 第一个 > target 的位置减 1
}

