type TreeNode struct {
	Val   int
	Left  *TreeNode
	Right *TreeNode
}

func rightSideView(root *TreeNode) []int {
	var res []int
	var dfs func(n *TreeNode, depth int)
	dfs = func(n *TreeNode, depth int) {
		if n == nil {
			return
		}
		if depth == len(res) {
			res = append(res, n.Val) // 先右后左，每层第一个到达的就是最右边的节点
		}
		dfs(n.Right, depth+1)
		dfs(n.Left, depth+1)
	}
	dfs(root, 0)
	return res
}

