problems.solution:
package main

func numIslands(grid [][]byte) int {
	m, n := len(grid), len(grid[0])
	// sink 把 (i, j) 所在的整座岛“淹掉”（改成 '0'），相当于标记为已访问
	var sink func(i, j int)
	sink = func(i, j int) {
		if i < 0 || i >= m || j < 0 || j >= n || grid[i][j] != '1' {
			return
		}
		grid[i][j] = '0'
		sink(i+1, j)
		sink(i-1, j)
		sink(i, j+1)
		sink(i, j-1)
	}
	count := 0
	for i := range grid {
		for j := range grid[i] {
			if grid[i][j] == '1' {
				count++ // 发现一座新岛
				sink(i, j)
			}
		}
	}
	return count
}

