problems.solution:
package main

func canFinish(numCourses int, prerequisites [][]int) bool {
	indeg := make([]int, numCourses)  // 每门课还有几门先修课没学
	next := make([][]int, numCourses) // 先修课 → 依赖它的课（邻接表）
	for _, p := range prerequisites {
		course, pre := p[0], p[1]
		next[pre] = append(next[pre], course)
		indeg[course]++
	}
	var queue []int
	for c, d := range indeg {
		if d == 0 {
			queue = append(queue, c) // 没有先修课，可以直接学
		}
	}
	done := 0
	for len(queue) > 0 {
		c := queue[0]
		queue = queue[1:]
		done++
		for _, nx := range next[c] {
			indeg[nx]--
			if indeg[nx] == 0 {
				queue = append(queue, nx)
			}
		}
	}
	return done == numCourses // 有环时环上的课入度永远不会变成 0
}

