problems.solution:
package main

func floodFill(image [][]int, sr int, sc int, color int) [][]int {
	old := image[sr][sc]
	if old == color {
		return image // 颜色本来就一样，不处理（否则 DFS 会无限递归）
	}
	var fill func(i, j int)
	fill = func(i, j int) {
		if i < 0 || i >= len(image) || j < 0 || j >= len(image[0]) || image[i][j] != old {
			return
		}
		image[i][j] = color
		fill(i+1, j)
		fill(i-1, j)
		fill(i, j+1)
		fill(i, j-1)
	}
	fill(sr, sc)
	return image
}

