problems.solution:
package main

import "slices"

func permute(nums []int) [][]int {
	var res [][]int
	path := make([]int, 0, len(nums))
	used := make([]bool, len(nums))
	var dfs func()
	dfs = func() {
		if len(path) == len(nums) {
			res = append(res, slices.Clone(path)) // 必须复制，path 之后还会被修改
			return
		}
		for i, v := range nums {
			if used[i] {
				continue
			}
			used[i] = true
			path = append(path, v)
			dfs()
			path = path[:len(path)-1] // 撤销选择
			used[i] = false
		}
	}
	dfs()
	return res
}

