			t.Errorf("permute(%v) = %v，期望 %v", c.nums, sorted(got), sorted(c.want))
		}
	}

	got := permute([]int{1, 2, 3, 4})
	seen := map[string]bool{}
	for _, p := range got {
		s := slices.Clone(p)
		slices.Sort(s)
		if !slices.Equal(s, []int{1, 2, 3, 4}) {
			t.Fatalf("permute([1 2 3 4]) 里有不是排列的结果 %v", p)
		}
		seen[fmt.Sprint(p)] = true
	}
	if len(got) != 24 || len(seen) != 24 {
		t.Errorf("permute([1 2 3 4]) 应该有 24 个不同的排列，得到 %d 个（不同的 %d 个）", len(got), len(seen))
	}
}

