package main

import "slices"

func subsets(nums []int) [][]int {
	var res [][]int
	var path []int
	var dfs func(start int)
	dfs = func(start int) {
		res = append(res, slices.Clone(path)) // 每个节点都是一个子集
		for i := start; i < len(nums); i++ {
			path = append(path, nums[i])
			dfs(i + 1) // 只往后选，避免 [1,2] 和 [2,1] 重复
			path = path[:len(path)-1]
		}
	}
	dfs(0)
	return res
}

