problems.solution:
package main

import "slices"

func combinationSum(candidates []int, target int) [][]int {
	slices.Sort(candidates)
	var res [][]int
	var path []int
	var dfs func(start, rest int)
	dfs = func(start, rest int) {
		if rest == 0 {
			res = append(res, slices.Clone(path))
			return
		}
		for i := start; i < len(candidates); i++ {
			c := candidates[i]
			if c > rest {
				break // 已排序，后面的数更大，也不可能
			}
			path = append(path, c)
			dfs(i, rest-c) // 可以重复选，所以下一层还从 i 开始
			path = path[:len(path)-1]
		}
	}
	dfs(0, target)
	return res
}

