problems.solution:
package main

func generateParenthesis(n int) []string {
	var res []string
	buf := make([]byte, 0, 2*n)
	var dfs func(open, closed int)
	dfs = func(open, closed int) {
		if len(buf) == 2*n {
			res = append(res, string(buf)) // string(buf) 会复制，不用担心 buf 之后被修改
			return
		}
		if open < n { // 还能放左括号
			buf = append(buf, '(')
			dfs(open+1, closed)
			buf = buf[:len(buf)-1]
		}
		if closed < open { // 右括号不能多于左括号
			buf = append(buf, ')')
			dfs(open, closed+1)
			buf = buf[:len(buf)-1]
		}
	}
	dfs(0, 0)
	return res
}

