	cases := []struct {
		n    int
		want []string
	}{
		{3, []string{"((()))", "(()())", "(())()", "()(())", "()()()"}},
		{1, []string{"()"}},
		{2, []string{"(())", "()()"}},
	}
	for _, c := range cases {
		got := generateParenthesis(c.n)
		slices.Sort(got)
		if !slices.Equal(got, c.want) {
			t.Errorf("generateParenthesis(%d) = %q，期望 %q", c.n, got, c.want)
		}
	}

	got := generateParenthesis(5)
	slices.Sort(got)
	if len(slices.Compact(slices.Clone(got))) != 42 {
		t.Errorf("n = 5 时应该有 42 个不同的组合，得到 %d 个", len(got))
	}
	for _, s := range got {
		if len(s) != 10 || !valid(s) {
			t.Errorf("n = 5 时生成了无效的组合 %q", s)
		}
	}
